The demo analysis shows that the task divides the grid into blocks using separator rows and columns (filled with a uniform color). For each block, we count the number of "object" cells (non-background, non-separator). The output for each block is:
- 2 if there is exactly 1 object
- 1 if there are more or fewer than 1 object (but typically 2+ in this task)

I need to correctly extract blocks, separate background from objects, and apply this mapping rule.

```python
def transform(grid):
    from collections import Counter

    H, W = len(grid), len(grid[0])

    # Find separator rows (entirely uniform)
    sep_rows = []
    for r in range(H):
        if all(grid[r][c] == grid[r][0] for c in range(W)):
            sep_rows.append(r)

    # Find separator columns
    sep_cols = []
    for c in range(W):
        if all(grid[r][c] == grid[0][c] for r in range(H)):
            sep_cols.append(c)

    if not sep_rows or not sep_cols:
        return grid

    sep_color = grid[sep_rows[0]][0]

    # Build list of block row ranges
    r_ranges = []
    r = 0
    for sr in sorted(sep_rows):
        if r < sr:
            r_ranges.append((r, sr))
        r = sr + 1
    if r < H:
        r_ranges.append((r, H))

    # Build list of block col ranges
    c_ranges = []
    c = 0
    for sc in sorted(sep_cols):
        if c < sc:
            c_ranges.append((c, sc))
        c = sc + 1
    if c < W:
        c_ranges.append((c, W))

    # Build output grid
    out = []

    for (r_start, r_end) in r_ranges:
        out_row = []
        for (c_start, c_end) in c_ranges:
            # Count all non-separator values in block
            block_vals = []
            for r in range(r_start, r_end):
                for c in range(c_start, c_end):
                    val = grid[r][c]
                    if val != sep_color:
                        block_vals.append(val)

            if not block_vals:
                out_row.append(0)
                continue

            # Find background (most common color)
            counts = Counter(block_vals)
            if counts:
                bg_count = counts.most_common(1)[0][1]
            else:
                bg_count = 0

            # Object count = total - background count
            obj_count = len(block_vals) - bg_count

            # If count == 1, output 2, else output 1
            out_row.append(2 if obj_count == 1 else 1)
        out.append(out_row)

    return out if out else [[1]]
